-- Rebuild nouns_lexicon from full_dictionary_enriched.json
PRAGMA foreign_keys = OFF;
DROP TABLE IF EXISTS nouns_lexicon;
CREATE TABLE nouns_lexicon (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  pashto_word TEXT NOT NULL UNIQUE,
  romanized TEXT,
  gender TEXT,
  number TEXT,
  plural_forms TEXT,
  inflection_type TEXT,
  english TEXT,
  created_at INTEGER DEFAULT (strftime('%s','now')),
  updated_at INTEGER DEFAULT (strftime('%s','now'))
);
CREATE INDEX IF NOT EXISTS idx_nouns_lexicon_pashto ON nouns_lexicon (pashto_word);
CREATE INDEX IF NOT EXISTS idx_nouns_lexicon_gender ON nouns_lexicon (gender);
